import os
import google.cloud.documentai_v1 as documentai

def normalize_expense(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us") 
    processor_id = os.environ.get("GOOGLE_CLOUD_DOCUMENTAI_EXPENSE_PROCESSOR_ID")

    if not project_id or not processor_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_DOCUMENTAI_EXPENSE_PROCESSOR_ID environment variables must be set.")

    documentai_client = documentai.DocumentProcessorServiceClient()
    processor_name = documentai_client.processor_path(project_id, location, processor_id)

    # The payload is expected to be base64 encoded document content, e.g., an image or PDF.
    raw_document = documentai.RawDocument(
        content=payload,
        mime_type="application/pdf" # Assuming PDF, adjust if other types are expected
    )

    request = documentai.ProcessRequest(
        name=processor_name,
        raw_document=raw_document
    )

    response = documentai_client.process_document(request=request)
    document = response.document

    # Initialize a dictionary for the normalized expense data
    normalized_expense_data = {
        "items": [],
        "currency": None,
        "total_amount": None,
        "expense_date": None,
        "supplier_name": None,
        "invoice_id": None
    }

    # Extract key-value pairs (fields)
    for entity in document.entities:
        if entity.type_ == "total_amount":
            normalized_expense_data["total_amount"] = float(entity.mention_text) if entity.mention_text else None
            if entity.normalized_value and entity.normalized_value.currency_code:
                normalized_expense_data["currency"] = entity.normalized_value.currency_code
        elif entity.type_ == "expense_date":
            if entity.normalized_value and entity.normalized_value.date_value:
                # Document AI returns date_value as a Date object which has year, month, day attributes
                date_val = entity.normalized_value.date_value
                normalized_expense_data["expense_date"] = f"{date_val.year:04d}-{date_val.month:02d}-{date_val.day:02d}"
            else:
                normalized_expense_data["expense_date"] = entity.mention_text
        elif entity.type_ == "supplier_name":
            normalized_expense_data["supplier_name"] = entity.mention_text
        elif entity.type_ == "invoice_id":
            normalized_expense_data["invoice_id"] = entity.mention_text
        elif entity.type_ == "line_item":
            item = {}
            for prop in entity.properties:
                if prop.type_ == "amount":
                    item["amount"] = float(prop.mention_text) if prop.mention_text else None
                elif prop.type_ == "description":
                    item["description"] = prop.mention_text
                elif prop.type_ == "quantity":
                    item["quantity"] = float(prop.mention_text) if prop.mention_text else None
            if item:
                normalized_expense_data["items"].append(item)

    result = normalized_expense_data
    return result
